/**
 * IWAC Visualizations — Reference dashboard (orchestrator)
 *
 * Per-item view for the `references` subset (the bibliography: books,
 * chapters, journal articles, theses, reports, reviews, communications,
 * blog posts — resource templates 10–14, 16–18 on islam.zmo.de). Loads
 * `asset/data/reference-dashboards/{o_id}.json` (generated by
 * scripts/generate_reference_dashboards.py) and renders:
 *
 *   1. The LDA topic line — the one derived value the item page has no
 *      equivalent for. There used to be a stat-card row above it (type /
 *      authors / year / publisher / pages / words / language / DOI), but
 *      every one of those fields is bibliographic metadata Omeka already
 *      renders on the same page, so the row only restated the item header
 *      in a second visual idiom.
 *   2. A review line, when `bibo:reviewOf` applies — what this work
 *      reviews, or which works in the bibliography review it.
 *   3. `siblingSparkline` — where this work sits in the bibliography's
 *      own publication timeline.
 *   4. `similarItems` — the closest works in the bibliography, by
 *      cosine similarity over `embedding_OCR`.
 *   5. `similarItems` — the closest *newspaper articles*: the reverse of
 *      the bridge on the article dashboards. Both corpora were embedded
 *      by the same model into the same space, so a scholarly work can be
 *      ranked against the press.
 *
 * Slots 4 and 5 depend on the 2026-07 full-text pipeline and are absent
 * for the ~half of the bibliography with no extracted text; the layout
 * elides them per item rather than showing empty panels.
 *
 * Dependencies: dashboard-layout + sibling-sparkline + similar-items
 * renderers (declared via the partial's $needs['renderers']).
 */
(function () {
    'use strict';

    var ns = window.IWACVis;
    if (!ns || !ns.panels || !ns.dashboardLayout) {
        console.warn('IWACVis reference dashboard: missing dependencies — check script load order');
        return;
    }
    var P  = ns.panels;
    var DL = ns.dashboardLayout;

    DL.register('reference', [
        { chart: 'siblingSparkline', wide: true,
          dataKey: 'sparkline',
          title: 'This work in the bibliography',
          description: 'desc_reference_activity' },
        { chart: 'similarItems', wide: true,
          dataKey: 'semantic_neighbors',
          title: 'Closest works in the bibliography',
          description: 'desc_reference_similar',
          options: { max: 8, lowSignal: 0 } },
        { chart: 'similarItems', wide: true,
          dataKey: 'press_neighbors',
          title: 'Press coverage this resembles',
          description: 'desc_reference_press',
          options: { max: 8, lowSignal: 0 } }
    ]);

    /* ----------------------------------------------------------------- */
    /*  Topic line                                                        */
    /* ----------------------------------------------------------------- */

    /**
     * The topic is set as a line of prose rather than a figure, because it
     * needs a qualifier a stat card has no room for: the label is machine-
     * generated top words, and the bibliography is modelled twice (French
     * and English) over shared columns, so the topic number alone means
     * nothing without its model — hence the `title` naming it.
     *
     * It is also the only derived value on this dashboard that isn't a
     * panel, which is why it survived the removal of the metrics row: the
     * rest of that row restated the item page's own bibliographic header.
     */
    function buildTopicLine(metrics) {
        if (!metrics || !metrics.topic) return null;
        var line = P.el('p', 'iwac-vis-reference__topic');
        line.appendChild(P.el('span', 'iwac-vis-reference__topic-label',
            P.t('reference_topic_label')));
        line.appendChild(P.el('span', 'iwac-vis-reference__topic-words', metrics.topic));
        line.title = metrics.topic_model
            ? P.t('reference_topic_model', { model: metrics.topic_model })
            : P.t('reference_topic_generated');
        return line;
    }

    /** Link to an item page, or plain text when we hold no record for it. */
    function itemLink(entry, siteBase) {
        if (entry && entry.o_id) {
            var a = document.createElement('a');
            a.href = (siteBase || '') + '/item/' + entry.o_id;
            a.textContent = entry.title || ('#' + entry.o_id);
            return a;
        }
        return document.createTextNode((entry && entry.title) || '');
    }

    /**
     * The reviewOf relation, in whichever direction applies. Rendered as
     * prose because it is a bibliographic fact about two works, not a
     * measurement — a chart would dress it up as something it isn't.
     */
    function buildReviewLine(reviews, siteBase) {
        if (!reviews) return null;
        var wrap = P.el('div', 'iwac-vis-reference__reviews');
        if (reviews.reviews) {
            var p = P.el('p', 'iwac-vis-reference__review-of');
            p.appendChild(document.createTextNode(P.t('reference_reviews_prefix') + ' '));
            p.appendChild(itemLink(reviews.reviews, siteBase));
            wrap.appendChild(p);
        }
        if (reviews.reviewed_by && reviews.reviewed_by.length) {
            var q = P.el('p', 'iwac-vis-reference__reviewed-by');
            q.appendChild(document.createTextNode(P.t('reference_reviewed_by_prefix') + ' '));
            reviews.reviewed_by.forEach(function (entry, i) {
                if (i > 0) q.appendChild(document.createTextNode(', '));
                q.appendChild(itemLink(entry, siteBase));
            });
            wrap.appendChild(q);
        }
        return wrap.childNodes.length ? wrap : null;
    }

    /* ----------------------------------------------------------------- */
    /*  Bootstrap                                                         */
    /* ----------------------------------------------------------------- */

    function initDashboard(container) {
        var itemId = container.dataset.itemId;
        if (!itemId) return;
        var basePath = container.dataset.basePath || '';
        var siteBase = container.dataset.siteBase || '';
        var url = basePath + P.DATA_BASE + 'reference-dashboards/' + itemId + '.json';

        P.fetchJSON(url)
            .then(function (data) {
                var loading = container.querySelector('.iwac-vis-reference__loading');
                if (loading) loading.remove();

                var body = P.el('div', 'iwac-vis-reference__body');
                container.appendChild(body);

                var topic = buildTopicLine(data.metrics);
                if (topic) body.appendChild(topic);
                var reviews = buildReviewLine(data.reviews, siteBase);
                if (reviews) body.appendChild(reviews);

                var activity = data.activity || null;
                var sparkline = activity ? {
                    years:     activity.years,
                    values:    activity.values,
                    highlight: activity.highlight,
                    caption:   P.t('references_count', {
                        count: P.formatNumber(activity.total || 0)
                    })
                } : null;

                DL.render(body, 'reference', {
                    sparkline:          sparkline,
                    semantic_neighbors: data.semantic_neighbors || [],
                    press_neighbors:    data.press_neighbors || []
                }, {
                    siteBase: siteBase,
                    basePath: basePath,
                    data:     data
                });
            })
            .catch(function (err) {
                // A missing file is the normal state for a reference the
                // generator has not covered, so this must not look like a
                // site error: drop the spinner and leave the item page as
                // Omeka rendered it.
                console.warn('IWACVis reference dashboard:', err);
                P.removeBlock(container);
            });
    }

    function init() {
        var containers = document.querySelectorAll('.iwac-vis-reference');
        for (var i = 0; i < containers.length; i++) {
            initDashboard(containers[i]);
        }
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();
